      "name": "PowerSeries.coeff_of_lt_order_toNat",
      "module_name": "Mathlib.RingTheory.PowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {φ : PowerSeries R}, ∀ n < φ.order.toNat, (PowerSeries.coeff n) φ = 0"
    }
  ]
